        };
      }
    }
  };
}


const GMAIL_TOKEN_CONNECTORS = ['gmail', 'google-calendar', 'google-drive', 'google-tasks'];

function gmailAuthFailure(cause) {
  const code = String(cause?.code || '');
  const http = Number(cause?.status || 0);
  return http === 401 || http === 403 || /AUTH_REQUIRED|_AUTH$/.test(code);
}

async function gmailNativeRead({ resolveAccessToken, fetchImpl, context, url, method, body, code }) {
  for (const connectorId of GMAIL_TOKEN_CONNECTORS) {
    try {
      const token = await tokenFor(resolveAccessToken, connectorId, context);
      const result = await requestJson(fetchImpl, token, url, { method, body, code, signal: context?.signal });
      return { provider: 'google', body: result };
    } catch (cause) {
      if (gmailAuthFailure(cause)) continue;
      throw cause;
    }
  }
  // All four token sources were tried and none authorized Gmail. Returning
  // the last *other-service* error (e.g. GOOGLE_TASKS_AUTH_REQUIRED) hides the
  // actual missing Gmail authorization and blocks the founder proof forever.
  // A non-auth network/timeout failure has already been thrown above.
  throw error('GMAIL_AUTH_REQUIRED', 503);
}

async function gmailRequest({
  resolveAccessToken,
  fetchImpl,
  pipedreamRuntime,
  env,
  context,
  url,
  method = 'GET',
  body,
  code,
  provider = null,
} = {}) {
  const owner = context?.owner || env?.MELITURGOS_USER || 'owner';
  const viaPipedream = async () => {
    if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') return null;
    const proxied = await pipedreamRuntime.proxy({ owner, app: 'gmail', url, method, body, signal: context?.signal });
    return { provider: 'pipedream', body: proxied?.body || {} };
  };
  if (provider === 'pipedream') {
    const proxied = await viaPipedream();
    if (!proxied) throw error('PIPEDREAM_RUNTIME_UNAVAILABLE', 503);
    return proxied;
  }
  let nativeError = null;
  try {
    return await gmailNativeRead({ resolveAccessToken, fetchImpl, context, url, method, body, code });
  } catch (error_) {
    nativeError = error_;
  }
  try {
    const proxied = await viaPipedream();
    if (!proxied) throw nativeError;
    return proxied;
  } catch (fallbackError) {
    if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') throw nativeError;
    const combined = error(code + '_ALL_PATHS_FAILED', 503);
    combined.native_code = String(nativeError?.code || nativeError?.message || 'GMAIL_NATIVE_FAILED').slice(0, 160);
    combined.fallback_code = String(fallbackError?.code || fallbackError?.message || 'GMAIL_PIPEDREAM_FAILED').slice(0, 160);
    throw combined;
  }
}

function gmailHealthcheck(resolveAccessToken, fetchImpl, env, pipedreamRuntime, { protectedAction = false } = {}) {
  const owner = String(env?.MELITURGOS_USER || 'owner').trim() || 'owner';
  const probe = GMAIL_API + '/profile';
  return async () => {
    try {
      await gmailNativeRead({
        resolveAccessToken, fetchImpl, context: { owner }, url: probe, method: 'GET', code: 'GMAIL_HEALTH_FAILED',
      });
      return { status: protectedAction ? 'PROTECTED' : 'HEALTHY', transport: 'google' };
    } catch (nativeError) {
      if (!pipedreamRuntime || typeof pipedreamRuntime.proxy !== 'function') {
        const code = String(nativeError?.code || nativeError?.message || 'GMAIL_HEALTH_FAILED').slice(0, 180);
        const http = Number(nativeError?.status || 0);
        const unavailable = http === 401 || http === 403 || /AUTH_REQUIRED|_AUTH$/.test(code);
        return { status: unavailable ? 'UNAVAILABLE' : 'DEGRADED', reason: code };
      }
      try {
        await pipedreamRuntime.proxy({ owner, app: 'gmail', url: probe, method: 'GET' });
        return {
          status: protectedAction ? 'PROTECTED' : 'HEALTHY',
          transport: 'pipedream',
          native_reason: String(nativeError?.code || nativeError?.message || '').slice(0, 160),
        };
      } catch (fallbackError) {
        const reason = String(fallbackError?.code || fallbackError?.message || 'GMAIL_ALL_PATHS_FAILED').slice(0, 180);
        const accountMissing = /ACCOUNT_REQUIRED$/.test(reason);
        return { status: accountMissing ? 'DEGRADED' : 'UNAVAILABLE', reason };
      }
    }
  };
}

export function registerGoogleWorkspaceCapabilities(bus, { env = {}, fetchImpl = fetch, resolveAccessToken = null, pipedreamRuntime = null } = {}) {
  if (!bus || typeof bus.discover !== 'function') throw new TypeError('CAPABILITY_BUS_REQUIRED');
  const resolveToken = resolveAccessToken || fixedTokenResolver(env);

  bus.discover({
    id: 'gmail.messages.search',
    name: 'Gmail message search',
    category: 'communication',
    version: '1.0.0',
    provider: 'google',
    description: 'Searches Gmail with a bounded Gmail query and returns subject, sender, date and snippet of the first messages (never the body).',
    input_schema: {
      type: 'object',
      properties: {
        query: { type: 'string', minLength: 1, maxLength: 1000 },
        limit: { type: 'integer', minimum: 1, maximum: MAX_LIST },
      },
      required: ['query'],
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.gmail.read'],
    health: 'DEGRADED',
    healthcheck: gmailHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const q = text(input.query, 'GMAIL_QUERY_INVALID', 1000);
    const url = GMAIL_API + '/messages?' + query({ q, maxResults: listLimit(input.limit) });
    const listed = await gmailRequest({
      resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context, url, code: 'GMAIL_SEARCH_FAILED',
    });
    const body = listed.body || {};
    const ids = (Array.isArray(body.messages) ? body.messages : []).slice(0, listLimit(input.limit)).map(row => ({
      id: String(row.id || ''),
      thread_id: String(row.threadId || ''),
    }));
    // Identifiers alone are useless in a conversation: add subject, sender,
    // date and Gmail's short snippet for the first messages (metadata only,
    // never the body). A failed header read keeps the bare identifier.
    const headerFor = (headers, name) => String((Array.isArray(headers) ? headers : []).find(h => String(h?.name || '').toLowerCase() === name)?.value || '').slice(0, 300);
    const messages = await Promise.all(ids.map(async (row, index) => {
      if (index >= GMAIL_SEARCH_METADATA_MAX || !row.id) return row;
      try {
        const metaResult = await gmailRequest({
          resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
          url: GMAIL_API + '/messages/' + encodeURIComponent(row.id) + '?format=metadata&metadataHeaders=Subject&metadataHeaders=From&metadataHeaders=Date',
          code: 'GMAIL_METADATA_FAILED', provider: listed.provider,
        });
        const meta = metaResult.body;
        const headers = meta?.payload?.headers;
        return {
          ...row,
          subject: headerFor(headers, 'subject'),
          from: headerFor(headers, 'from'),
          date: headerFor(headers, 'date'),
          snippet: String(meta?.snippet || '').slice(0, 300),
          unread: Array.isArray(meta?.labelIds) ? meta.labelIds.includes('UNREAD') : null,
        };
      } catch {
        return row;
      }
    }));
    return { provider: listed.provider, query: q, messages, count: messages.length };
  });

  bus.discover({
    id: 'gmail.messages.read',
    name: 'Gmail message read',
    category: 'communication',
    version: '1.0.0',
    provider: 'google',
    description: 'Reads one Gmail message by fixed message id.',
    input_schema: {
      type: 'object',
      properties: { message_id: { type: 'string', minLength: 1, maxLength: 300 } },
      required: ['message_id'],
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.gmail.read'],
    health: 'DEGRADED',
    healthcheck: gmailHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const id = encodePath(input.message_id, 'GMAIL_MESSAGE_ID_INVALID');
    const read = await gmailRequest({
      resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
      url: GMAIL_API + '/messages/' + id + '?format=full', code: 'GMAIL_READ_FAILED',
    });
    return { provider: read.provider, message: read.body };
  });

  for (const [id, draft, approvalScope] of [
    ['gmail.drafts.create', true, 'gmail.drafts.create'],
    ['gmail.messages.send', false, 'gmail.messages.send'],
  ]) {
    bus.discover({
      id,
      name: draft ? 'Gmail draft create' : 'Gmail send message',
      category: 'communication',
      version: '1.0.0',
      provider: 'google',
      description: draft
        ? 'Creates one bounded Gmail draft after explicit owner approval.'
        : 'Sends one bounded plain-text Gmail message after explicit owner approval.',
      input_schema: {
        type: 'object',
        properties: {
          to: { type: 'array', minItems: 1, maxItems: 20, items: { type: 'string', minLength: 3, maxLength: 320 } },
          cc: { type: 'array', maxItems: 20, items: { type: 'string', minLength: 3, maxLength: 320 } },
          bcc: { type: 'array', maxItems: 20, items: { type: 'string', minLength: 3, maxLength: 320 } },
          subject: { type: 'string', minLength: 1, maxLength: 998 },
          body: { type: 'string', minLength: 1, maxLength: 100000 },
        },
        required: ['to', 'subject', 'body'],
        additionalProperties: false,
      },
      output_schema: objectOutput,
      risk: draft ? 'MEDIUM' : 'HIGH',
      permissions: [draft ? 'google.gmail.draft' : 'google.gmail.send'],
      approval: { required: true, scope: approvalScope, reason: draft ? 'GMAIL_DRAFT_MUTATION' : 'GMAIL_SEND_MUTATION' },
      health: 'DEGRADED',
    healthcheck: workspaceHealthcheck(resolveToken, fetchImpl, env, 'gmail', { protectedAction: true }),
      enabled: true,
    }, async (input, context) => {
      const token = await tokenFor(resolveToken, 'gmail', context);
      const raw = mimeMessage(input);
      const endpoint = draft ? GMAIL_API + '/drafts' : GMAIL_API + '/messages/send';
      const body = await requestJson(fetchImpl, token, endpoint, {
        method: 'POST',
        body: draft ? { message: { raw } } : { raw },
        code: draft ? 'GMAIL_DRAFT_CREATE_FAILED' : 'GMAIL_SEND_FAILED',
        signal: context?.signal,
      });
      return {
        provider: 'google',
        accepted: true,
        draft_id: draft ? String(body.id || '') : '',
        message_id: draft ? String(body.message?.id || '') : String(body.id || ''),
        thread_id: draft ? String(body.message?.threadId || '') : String(body.threadId || ''),
      };
    });
  }

  bus.discover({
    id: 'calendar.events.read',
    name: 'Google Calendar event search',
    category: 'planning',
    version: '1.1.0',
    provider: 'google+pipedream',
    description: 'Reads a bounded set of events from one Google calendar, using native Google first and the linked Pipedream account as an authenticated fallback.',
    input_schema: {
      type: 'object',
      properties: {
        calendar_id: { type: 'string', minLength: 1, maxLength: 300 },
        time_min: { type: 'string', maxLength: 80 },
        time_max: { type: 'string', maxLength: 80 },
        query: { type: 'string', maxLength: 1000 },
        limit: { type: 'integer', minimum: 1, maximum: MAX_LIST },
      },
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.calendar.read'],
    health: 'DEGRADED',
    healthcheck: calendarHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const calendarId = encodeURIComponent(text(input.calendar_id || 'primary', 'CALENDAR_ID_INVALID', 300));
    const params = query({
      singleEvents: 'true',
      orderBy: 'startTime',
      maxResults: listLimit(input.limit),
      timeMin: input.time_min ? text(input.time_min, 'CALENDAR_TIME_INVALID', 80) : '',
      timeMax: input.time_max ? text(input.time_max, 'CALENDAR_TIME_INVALID', 80) : '',
      q: input.query ? text(input.query, 'CALENDAR_QUERY_INVALID', 1000) : '',
    });
    const transport = await calendarRequest({
      resolveAccessToken: resolveToken,
      fetchImpl,
      pipedreamRuntime,
      env,
      context,
      url: CALENDAR_API + '/calendars/' + calendarId + '/events?' + params,
      code: 'CALENDAR_READ_FAILED',
    });
    const events = (Array.isArray(transport.body?.items) ? transport.body.items : []).slice(0, listLimit(input.limit));
    return {
      provider: transport.provider,
      calendar_id: input.calendar_id || 'primary',
      events,
      count: events.length,
    };
  });

  for (const spec of [
    { id: 'calendar.events.create', method: 'POST', action: 'create', permission: 'google.calendar.write', risk: 'HIGH' },
    { id: 'calendar.events.update', method: 'PATCH', action: 'update', permission: 'google.calendar.write', risk: 'HIGH' },
    { id: 'calendar.events.delete', method: 'DELETE', action: 'delete', permission: 'google.calendar.delete', risk: 'HIGH' },
  ]) {
    bus.discover({
      id: spec.id,
      name: 'Google Calendar event ' + spec.action,
      category: 'planning',
      version: '1.1.0',
      provider: 'google+pipedream',
      description: 'Mutates one Google Calendar event after explicit owner approval, using native Google first and Pipedream only as an authenticated fallback.',
      input_schema: {
        type: 'object',
        properties: {
          calendar_id: { type: 'string', minLength: 1, maxLength: 300 },
          event_id: { type: 'string', minLength: 1, maxLength: 300 },
          summary: { type: 'string', maxLength: 1000 },
          description: { type: 'string', maxLength: 12000 },
          location: { type: 'string', maxLength: 1000 },
          start: { type: 'string', maxLength: 80 },
          end: { type: 'string', maxLength: 80 },
          timeZone: { type: 'string', maxLength: 100 },
          attendees: { type: 'array', maxItems: 50, items: { type: 'string', minLength: 3, maxLength: 320 } },
        },
        ...(spec.action === 'create' ? { required: ['summary', 'start', 'end'] } : { required: ['event_id'] }),
        additionalProperties: false,
      },
      output_schema: objectOutput,
      risk: spec.risk,
      permissions: [spec.permission],
      approval: { required: true, scope: spec.id, reason: 'CALENDAR_EVENT_MUTATION' },
      health: 'DEGRADED',
      healthcheck: calendarHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime, { protectedAction: true }),
      enabled: true,
    }, async (input, context) => {
      const calendarId = encodeURIComponent(text(input.calendar_id || 'primary', 'CALENDAR_ID_INVALID', 300));
      const base = CALENDAR_API + '/calendars/' + calendarId + '/events';
      let url = base;
      let body;
      if (spec.action === 'create') body = calendarEvent(input);
      else {
        const eventId = encodePath(input.event_id, 'CALENDAR_EVENT_ID_INVALID');
        url += '/' + eventId;
        if (spec.action === 'update') body = calendarEvent(input, { partial: true });
      }
      const transport = await calendarRequest({
        resolveAccessToken: resolveToken,
        fetchImpl,
        pipedreamRuntime,
        env,
        context,
        url,
        method: spec.method,
        body,
        code: 'CALENDAR_' + spec.action.toUpperCase() + '_FAILED',
      });
      return {
        provider: transport.provider,
        calendar_id: input.calendar_id || 'primary',
        event_id: String(transport.body?.id || input.event_id || ''),
        accepted: true,
      };
    });
  }

  bus.discover({
    id: 'tasks.tasklists.read',
    name: 'Google Tasks lists read',
    category: 'planning',
    version: '1.0.0',
    provider: 'google+pipedream',
    description: 'Lists bounded Google Tasks task lists, using native Google first and the linked Pipedream account as fallback.',
    input_schema: {
      type: 'object',
      properties: { limit: { type: 'integer', minimum: 1, maximum: MAX_LIST } },
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.tasks.read'],
    health: 'DEGRADED',
    healthcheck: tasksHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const limit = listLimit(input.limit);
    const transport = await tasksRequest({
      resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
      url: TASKS_API + '/users/@me/lists?' + query({ maxResults: limit }), code: 'TASKLISTS_READ_FAILED',
    });
    const tasklists = (Array.isArray(transport.body?.items) ? transport.body.items : []).slice(0, limit);
    return { provider: transport.provider, tasklists, count: tasklists.length };
  });

  bus.discover({
    id: 'tasks.tasks.read',
    name: 'Google Tasks read',
    category: 'planning',
    version: '1.0.0',
    provider: 'google+pipedream',
    description: 'Lists bounded tasks in one Google Tasks task list, using native Google first and Pipedream as fallback.',
    input_schema: {
      type: 'object',
      properties: {
        tasklist_id: { type: 'string', minLength: 1, maxLength: 300 },
        limit: { type: 'integer', minimum: 1, maximum: MAX_LIST },
        show_completed: { type: 'boolean' },
      },
      required: ['tasklist_id'],
      additionalProperties: false,
    },
    output_schema: objectOutput,
    risk: 'LOW',
    permissions: ['google.tasks.read'],
    health: 'DEGRADED',
    healthcheck: tasksHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime),
    enabled: true,
  }, async (input, context) => {
    const tasklist = encodePath(input.tasklist_id, 'TASKLIST_ID_INVALID');
    const limit = listLimit(input.limit);
    const transport = await tasksRequest({
      resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
      url: TASKS_API + '/lists/' + tasklist + '/tasks?' + query({
        maxResults: limit,
        showCompleted: input.show_completed === false ? 'false' : 'true',
      }), code: 'TASKS_READ_FAILED',
    });
    const tasks = (Array.isArray(transport.body?.items) ? transport.body.items : []).slice(0, limit);
    return { provider: transport.provider, tasklist_id: input.tasklist_id, tasks, count: tasks.length };
  });

  for (const spec of [
    { id: 'tasks.tasks.create', method: 'POST', action: 'create', permission: 'google.tasks.write' },
    { id: 'tasks.tasks.update', method: 'PATCH', action: 'update', permission: 'google.tasks.write' },
    { id: 'tasks.tasks.delete', method: 'DELETE', action: 'delete', permission: 'google.tasks.delete' },
  ]) {
    bus.discover({
      id: spec.id,
      name: 'Google Tasks ' + spec.action,
      category: 'planning',
      version: '1.0.0',
      provider: 'google+pipedream',
      description: 'Mutates one Google task after explicit owner approval, using native Google first and Pipedream as fallback.',
      input_schema: {
        type: 'object',
        properties: {
          tasklist_id: { type: 'string', minLength: 1, maxLength: 300 },
          task_id: { type: 'string', minLength: 1, maxLength: 300 },
          title: { type: 'string', maxLength: 1024 },
          notes: { type: 'string', maxLength: 8192 },
          due: { type: 'string', maxLength: 80 },
          status: { type: 'string', enum: ['needsAction', 'completed'] },
        },
        required: spec.action === 'create' ? ['tasklist_id', 'title'] : ['tasklist_id', 'task_id'],
        additionalProperties: false,
      },
      output_schema: objectOutput,
      risk: 'HIGH',
      permissions: [spec.permission],
      approval: { required: true, scope: spec.id, reason: 'GOOGLE_TASK_MUTATION' },
      health: 'DEGRADED',
    healthcheck: tasksHealthcheck(resolveToken, fetchImpl, env, pipedreamRuntime, { protectedAction: true }),
      enabled: true,
    }, async (input, context) => {
      const tasklist = encodePath(input.tasklist_id, 'TASKLIST_ID_INVALID');
      let url = TASKS_API + '/lists/' + tasklist + '/tasks';
      let body;
      if (spec.action === 'create') body = taskBody(input);
      else {
        const taskId = encodePath(input.task_id, 'TASK_ID_INVALID');
        url += '/' + taskId;
        if (spec.action === 'update') body = taskBody(input, { partial: true });
      }
      const transport = await tasksRequest({
        resolveAccessToken: resolveToken, fetchImpl, pipedreamRuntime, env, context,
        url, method: spec.method, body,
        code: 'TASKS_' + spec.action.toUpperCase() + '_FAILED',
      });
      return { provider: transport.provider, tasklist_id: input.tasklist_id, task_id: String(transport.body?.id || input.task_id || ''), accepted: true };
    });
  }

  return Object.freeze([
    'gmail.messages.search',
    'gmail.messages.read',
    'gmail.drafts.create',
    'gmail.messages.send',
    'calendar.events.read',
    'calendar.events.create',
    'calendar.events.update',
    'calendar.events.delete',
    'tasks.tasklists.read',
    'tasks.tasks.read',
    'tasks.tasks.create',
    'tasks.tasks.update',
    'tasks.tasks.delete',
  ]);
}

